// Valida y normaliza el input. Espera:
// {
//   "message": "texto del cliente",
//   "history": [{ role: 'user'|'assistant', content: '...' }, ...] (opcional, max 10)
//   "contact_name": "opcional",
//   "contact_phone": "opcional"
// }

const body = $input.item.json.body || $input.item.json;
const message = (body.message || '').trim();
const history = Array.isArray(body.history) ? body.history.slice(-10) : [];
const contactName = body.contact_name || null;
const contactPhone = body.contact_phone || null;

if (!message) {
  throw new Error('El campo "message" es obligatorio');
}

return {
  json: { message, history, contact_name: contactName, contact_phone: contactPhone }
};

// Construye el contexto de la KB a inyectar en el system prompt
const ragResp = $input.item.json;
const input = $('Validar input').item.json;
const resultados = ragResp.resultados || [];

// Filtra solo los resultados con similarity > 0.3 (umbral de relevancia)
const relevantes = resultados.filter(r => r.similarity > 0.3);

let kbContext = '';
if (relevantes.length === 0) {
  kbContext = 'No se encontraron servicios relevantes en el catalogo para esta consulta. Si el cliente pregunta por un servicio especifico, escala a humano.';
} else {
  kbContext = 'SERVICIOS DEL CATALOGO RELEVANTES A LA CONSULTA (ordenados por relevancia):\n\n';
  relevantes.forEach((r, i) => {
    kbContext += `[${i + 1}] ${r.nombre} (slug: ${r.slug}, similarity: ${r.similarity.toFixed(2)})\n`;
    kbContext += `   - ${r.descripcion_corta}\n`;
    if (r.precio_setup) kbContext += `   - Precio setup: ${r.precio_setup}\n`;
    if (r.precio_recurrente) kbContext += `   - Precio recurrente: ${r.precio_recurrente}\n`;
    if (r.tiempo_entrega) kbContext += `   - Tiempo entrega: ${r.tiempo_entrega}\n`;
    if (r.entregables && r.entregables.length) {
      kbContext += `   - Entregables principales: ${r.entregables.slice(0, 3).join('; ')}\n`;
    }
    kbContext += '\n';
  });
}

return {
  json: {
    message: input.message,
    history: input.history,
    contact_name: input.contact_name,
    contact_phone: input.contact_phone,
    kb_context: kbContext,
    rag_results: relevantes
  }
};

// Construye los mensajes para OpenAI Chat Completions
// system + (history) + user (mensaje actual)

const input = $input.item.json;

const systemPrompt = `Sos el asistente de eXcalando, una agencia de capacidades digitales con IA en Colombia. Atendes WhatsApp de PyMEs (5-50 empleados, duenos 35-55 anos, no tecnicos).

IDENTIDAD
- Te presentas como "el asistente de eXcalando".
- Si preguntan "sos un bot?": "Si, soy un asistente IA del equipo. Detras hay personas reales que intervienen cuando hace falta. En que te puedo ayudar?"

PERSONALIDAD
- Profesional pero cercano. Tutea estricto (tu, NUNCA vos, NUNCA usted).
- Directo. Sin jerga inflada.
- Honesto. Si no sabes algo, lo decis y escalas.
- Si detectas frustracion, validas primero ("Entiendo la molestia, dejame revisar") antes de proponer solucion.

FORMATO
- WhatsApp friendly. 3-4 lineas max por mensaje.
- Si la respuesta es larga, partila en 2-3 mensajes con saltos.
- Emojis con moderacion (1-2 max por respuesta).
- Saltos de linea para legibilidad.

OBJETIVO POR CONVERSACION (en este orden)
1. Entender que busca el cliente (1-2 preguntas)
2. Mostrarle el match con un servicio nuestro (1 mensaje)
3. Empujar al siguiente paso: Score Digital o agendar 30min
4. Si la conversacion se enfria, no insistir mas de 2 veces

QUE HACER (sin pedir permiso)
- Responder con base en los servicios del catalogo que te paso abajo
- Calificar (sector, tamano empresa, necesidad puntual)
- Mandar link al Score: https://excalando.com

QUE NO HACER (escala a humano si pasa)
- Negociar precios fuera del catalogo
- Comprometer fechas exactas (siempre "X dias aprox")
- Comparar con competencia ("preferimos no comentar otras empresas")
- Inventar info no presente en KB
- Cerrar ventas > $5M COP solo
- Discutir legal / contratos / NDAs

ESCALACION INMEDIATA si:
- Cliente escribe "humano", "persona", "alguien real", "tu jefe", "el dueno"
- Detectas lenguaje agresivo
- Menciona: "demanda", "denuncia", "estafa", "fraude", "abogado"
- Preguntas legales/contractuales

En esta FASE 1 todavia no tenes herramientas de escalar/agendar/registrar. Si toca escalar, dile al cliente: "Esto lo veo con un colega del equipo y te confirmo en un toque" y deja claro en tu respuesta que se necesita intervencion humana.

---

${input.kb_context}

---

Reglas finales:
- Responde SOLO con la respuesta al cliente, sin meta-comentarios.
- Si el cliente saluda primero ("hola", "buenos dias"), responde corto y pregunta en que puedes ayudar.
- Cuando muestres un servicio del catalogo, menciona el precio si esta en la KB y un beneficio concreto (no la descripcion completa).`;

const messages = [{ role: 'system', content: systemPrompt }];

// Agregar historial si existe
if (Array.isArray(input.history) && input.history.length > 0) {
  input.history.forEach(h => {
    if (h.role && h.content) {
      messages.push({ role: h.role, content: h.content });
    }
  });
}

// Mensaje actual del cliente
messages.push({ role: 'user', content: input.message });

return {
  json: {
    messages,
    contact_name: input.contact_name,
    contact_phone: input.contact_phone,
    rag_results: input.rag_results
  }
};

// Parsea la respuesta de OpenAI y construye la respuesta final
const openaiResp = $input.item.json;
const originalInput = $('Construir contexto KB').item.json;
const promptData = $('Construir prompt OpenAI').item.json;

const respuesta = openaiResp.choices?.[0]?.message?.content?.trim() || '';
const tokensUsed = openaiResp.usage?.total_tokens || 0;
const costEstimateUsd = (openaiResp.usage?.prompt_tokens || 0) * 0.0000025 + (openaiResp.usage?.completion_tokens || 0) * 0.00001;

if (!respuesta) {
  throw new Error('OpenAI no devolvio respuesta');
}

// Heuristica simple para detectar si la respuesta sugiere escalacion
const escalationKeywords = ['lo veo con un colega', 'colega del equipo', 'humano', 'intervencion humana', 'lo confirmo'];
const needsHumanReview = escalationKeywords.some(k => respuesta.toLowerCase().includes(k));

return {
  json: {
    ok: true,
    respuesta,
    metadata: {
      contact_name: originalInput.contact_name,
      contact_phone: originalInput.contact_phone,
      query_original: originalInput.message,
      servicios_consultados: (promptData.rag_results || []).map(r => ({ slug: r.slug, similarity: r.similarity })),
      needs_human_review: needsHumanReview,
      tokens_used: tokensUsed,
      cost_estimate_usd: parseFloat(costEstimateUsd.toFixed(6))
    }
  }
};
